static int readAllInts(int *values, int capacity) {
    char input[1048576];
    size_t length = fread(input, 1, sizeof(input) - 1, stdin);
    input[length] = '\0';
    char *cursor = input;
    int count = 0;
    while (*cursor) {
        char *end;
        long value = strtol(cursor, &end, 10);
        if (end == cursor) { cursor++; continue; }
        if (count == capacity) return -1;
        values[count++] = (int)value;
        cursor = end;
    }
    return count;
}

