", "class Solution:

	def genIp(self, s):
		res = []

		def BT(i, address):
			if i == len(s):
				if len(address) == 4:
					res.append('.'.join(map(str, address)))
				return
			if address[-1] != 0 and address[-1] * 10 + int(s[i]) <= 255:
				lastItem = address[-1]
				address[-1] = lastItem * 10 + int(s[i])
				BT(i + 1, address)
				address[-1] = lastItem
			if len(address) < 4:
				address.append(int(s[i]))
				BT(i + 1, address)
