class Solution:

	def genIp(self, S: str) -> List[str]:

		def dfs(s, ip, ips):
			if not s:
				if len(ip) == 4:
					ips.append('.'.join(ip))
				return
			for i in range(1, 4):
				if i <= len(s) and (i == 1 or s[0] != '0') and (int(s[:i]) <= 255):
