", "class Solution:

	def genIp(self, s):

		def check(s):
			n = len(s)
			if n <= 0 or n > 3:
				return False
			if s[0] == '0' and n > 1:
				return False
			if int(s) < 0 or int(s) > 255:
				return False
			return True

		def generate(s, i, j, k, n):
			s1 = s[0:i]
			s2 = s[i:j]
			s3 = s[j:k]
			s4 = s[k:n]
			if check(s1) and check(s2) and check(s3) and check(s4):
				return s1 + '.' + s2 + '.' + s3 + '.' + s4
			else:
				return ''
		n = len(s)
		if n < 4:
			return []
		ans = []
		for i in range(n):
			for j in range(i + 1, n):
				for k in range(j + 1, n):
					string = generate(s, i, j, k, n)
					if len(string) > 0:
						ans.append(string)
		return ans
