", "def binSer(string, x):
	mid = len(string) // 2
	if string[mid] == x:
		return 1
	if ord(string[mid]) < ord(x):
		for i in string[mid + 1:]:
			if i == x:
				return 1
		return -1
	if ord(string[mid]) > ord(x):
		for i in string[:mid]:
			if i == x:
				return 1
		return -1

