	string = input()
	v = ['a', 'e', 'i', 'o', 'u']
	if len(string) == 1:
		if string[0] == 'n':
			return 'YES'
		if binSer(v, string[0]) == -1:
			return 'NO'
		return 'YES'
	for i in range(len(string) - 1):
		if string[i] == 'n':
