", "def apply(A, p):
	A[:p] = reversed(A[:p])
	for i in range(p):
		if A[i] == '1':
			A[i] = '0'
		else:
			A[i] = '1'

def brute(n, A, B):
	result = []
	for i in range(n - 1, 0, -1):
		if A[i] != B[i]:
			if A[0] != A[i]:
				result.append(1)
				apply(A, 1)
			result.append(i + 1)
			apply(A, i + 1)
	if A[0] != B[0]:
		result.append(1)
		apply(A, 1)
	return result

