", "def do(s, x):
	for i in range(x + 1):
		s[i] = (s[i] + 1) % 2
	for i in range(x // 2 + 1):
		(s[i], s[x - i]) = (s[x - i], s[i])
	return s

def solve(n, a, b):
	ans = [0]
	for i in range(n - 1, -1, -1):
		if a[i] != b[i]:
			if a[0] != b[i]:
				a = do(a, i)
				ans += [i + 1]
				ans[0] += 1
			else:
				a[0] = (a[0] + 1) % 2
				a = do(a, i)
				ans += [1, i + 1]
				ans[0] += 2
	return ans

