				self.append(x)
			elif not ~self.type and x < 0:
				self.append(x)
			return
		t = self[-1]
		if t < 0:
			if 0 > x > t:
				self[-1] = x
			elif x >= 0:
				self.append(x)
		elif x > t > 0:
			self[-1] = x
		elif x < 0:
