	n = len(nums)
	dp_plus = [(0, 0)] * (n + 1)
	dp_minus = [(0, 0)] * (n + 1)
	for (idx, x) in enumerate(nums):
		ii = idx + 1
		if x > 0:
			(p, m) = (dp_plus, dp_minus)
