", "def palindrome(x, word) -> int:
	(beg, fin) = (0, len(word) - 1)
	changes = 0
	while beg <= fin:
		if word[beg] == word[fin]:
			(beg, fin) = (beg + 1, fin - 1)
			continue
		if word[beg] == x:
			beg += 1
			changes += 1
			continue
		if word[fin] == x:
			fin -= 1
			changes += 1
			continue
		return -1
	return changes

