class MonoQueue:

	def __init__(self, inc=True):
		self.queue = []
		self.inc = inc

	def popfront(self, n):
		if self.queue[0] == n:
			self.queue.pop(0)
		return

	def push(self, n):
		while self.queue:
			if self.inc is True and self.queue[-1] > n:
				self.queue.pop(-1)
			elif self.inc is False and self.queue[-1] < n:
				self.queue.pop(-1)
			else:
				break
		self.queue.append(n)
		return

	def is_empty(self):
		return len(self.queue) == 0

	def top(self):
		return self.queue[0]
