def build(a):
	if len(a) == 0:
		return None
	if len(a) == 1:
		return Node(a[0], None, None)
	level = math.log2(len(a))
	level = math.ceil(level) + (1 if int(level) == level else 0)
	if len(a) >= 2 ** (level - 2) * 3 - 1:
		root = 2 ** (level - 1) - 1
	else:
		root = len(a) - 2 ** (level - 2)
	left = build(a[:root])
	right = build(a[root + 1:])
	return Node(a[root], left, right)

