class MinHeap:

	def __init__(self):
		self.array = []
		self.length = 0

	def insert(self, num):
		self.array.append(num)
		self.length += 1
		child = self.length - 1
		parent = (child - 1) // 2
		while parent >= 0 and self.array[child] > self.array[parent]:
			(self.array[child], self.array[parent]) = (self.array[parent], self.array[child])
			child = parent
			parent = (child - 1) // 2

	def pop(self):
		result = self.array[0]
		self.array[0] = self.array[-1]
		self.array.pop()
		self.length -= 1
		parent = 0
		child = 1
		while child < self.length:
			if child + 1 < self.length and self.array[child + 1] > self.array[child]:
				child += 1
			if self.array[child] > self.array[parent]:
				(self.array[child], self.array[parent]) = (self.array[parent], self.array[child])
				parent = child
				child = 2 * child + 1
			else:
				break
		return result

	def peak(self):
		return self.array[0]

	def setPeak(self, num):
		self.array[0][0] = num

