	def __init__(self, n):
		self.parents = [0] * n
		self.sizes = [0] * n
		for i in range(n):
			self.parents[i] = i
			self.sizes[i] = 1

	def find(self, u):
		if self.parents[u] == u:
			return u
		else:
			self.parents[u] = self.find(self.parents[u])
			return self.parents[u]

	def union(self, u, v):
		rootu = self.find(u)
		rootv = self.find(v)
		if rootu == rootv:
			return
		if self.sizes[rootu] < self.sizes[rootv]:
			self.parents[rootu] = rootv
			self.sizes[rootv] += self.sizes[rootu]
		else:
			self.parents[rootv] = rootu
			self.sizes[rootu] += self.sizes[rootv]

