		group_counts_ = collections.Counter()
		_id_ = 0
		previous_count = 0
		for row in range(N):
			for col in range(M):
				if grid[row][col] == 1 and visited[row][col] == 0:
					_id_ += 1
					visited[row][col] = 1
					stack = [(row, col)]
					group_ids_[row, col] = _id_
					while stack:
						(r, c) = stack.pop()
						for (newr, newc) in [(r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)]:
