								stack.append((newr, newc))
								group_ids_[newr, newc] = _id_
					group_counts_[_id_] = sum([sum(l) for l in visited]) - previous_count
					previous_count = sum([sum(l) for l in visited])
		biggest = 0
		hasZero = False
		for r in range(N):
