		prefix_xor = arr[0]
		self.insert(prefix_xor)
		for n in arr[1:]:
			prefix_xor = prefix_xor ^ n
			max_xor = max(max_xor, prefix_xor, self._find_Max_XOR(prefix_xor))
			self.insert(prefix_xor)
		return max_xor

