class Solution:

	def maxSubarrayXOR(self, N, arr):
		pref_xor = [None] * (N + 1)
		pref_xor[0] = 0
		t = 0
		for i in range(N):
			t ^= arr[i]
			pref_xor[i + 1] = t

		def insert(root, bin_str):
			for bit_chr in bin_str:
				bit = int(bit_chr)
				if bit not in root:
					root[bit] = {}
				root = root[bit]

		def findMaxXor(root, bin_str):
			target_bin_str = ''.join(('0' if c == '1' else '1' for c in bin_str))
			best_str = ''
			for bit_chr in target_bin_str:
				bit = int(bit_chr)
				if bit in root:
					best_str += str(bit)
					root = root[bit]
				else:
					best_str += str(1 ^ bit)
					root = root[1 ^ bit]
			best = int(best_str, 2)
			num = int(bin_str, 2)
			return best ^ num
		max_num = max(pref_xor)
		k = math.floor(math.log(max_num, 2)) + 1
		for (i, num) in enumerate(pref_xor):
			pref_xor[i] = bin(num)[2:].zfill(k)
		trie = {}
		max_xor = 0
		for num_str in pref_xor:
			insert(trie, num_str)
			max_xor = max(max_xor, findMaxXor(trie, num_str))
		return max_xor
