class BST:

	def __init__(self) -> None:
		self.root = Node()

	def add(self, num):
		val = INT_VAL
		node = self.root
		while val > 0:
			if val & num != 0:
				if node.right is None:
					node.right = Node()
				node = node.right
			else:
				if node.left is None:
					node.left = Node()
