	def __init__(self):
		self.data = []

	def push(self, x):
		self.data.append(x)

	def peek(self):
		return self.data[-1]

	def delete(self):
		return self.data.pop()

	def is_empty(self):
		return len(self.data) == 0

def append(stack, word):
	last_word = ''
	if not stack.is_empty():
		last_word = stack.peek()
	stack.push(last_word + word)

def delete(stack, k):
	last_word = stack.peek()
	word = last_word[:-k]
	stack.push(word)

def print_stack(stack, k):
	word = stack.peek()
	print(word[k - 1])

def undo(stack):
	stack.delete()
