		for v in range(1000, N):
			if not self.prime[v]:
				continue
			rs = (v % 1000, v // 1000 * 1000 + v % 100, v // 100 * 100 + v % 10, v // 10 * 10)
			for d in range(10):
				for nv in [d * m + r for (r, m) in zip(rs, (1000, 100, 10, 1))]:
					if nv != v and nv > 1000 and self.prime[nv]:
						self.adjs[v].add(nv)

