import itertools
from collections import deque
MAX_N = 9999

class MITM_Side:

	def __init__(self, n):
		self.visited = set([n])
		self.frontline = deque([n])

class Solution:

	def _mark_multiples_as_not_prime(self, n):
		for i in range(n * n, MAX_N + 1, n):
			self.prime[i] = False

	def __init__(self):
		self.prime = [True for i in range(MAX_N + 1)]
		self.prime[0] = self.prime[1] = False
		for i in range(2, int(math.sqrt(MAX_N))):
			if self.prime[i]:
				self._mark_multiples_as_not_prime(i)

	def _generate_all_neighbors_on_position(self, n, position):
		position_coefficient = 10 ** position
		digit_at_position = n // position_coefficient % 10
		n_template = n - digit_at_position * position_coefficient
		start = 1 if position == 3 else 0
		neighbor_primes = []
		for i in range(start, 10):
			nn = n_template + i * position_coefficient
			if self.prime[nn] and nn != n:
				neighbor_primes.append(nn)
		return neighbor_primes

	def get_all_prime_neighbors(self, n):
		return list(itertools.chain(self._generate_all_neighbors_on_position(n, 3), self._generate_all_neighbors_on_position(n, 2), self._generate_all_neighbors_on_position(n, 1), self._generate_all_neighbors_on_position(n, 0)))

	def shortestPath(self, Num1, Num2):
		side1 = MITM_Side(Num1)
		side2 = MITM_Side(Num2)
		rounds_count = 0
		if Num1 == Num2:
			return rounds_count
		while rounds_count < len(self.prime):
			rounds_count += 1
			(side1, side2) = (side2, side1)
			new_frontline = deque()
			for n in side1.frontline:
				for prime_neighbor in self.get_all_prime_neighbors(n):
