def extremum_permutations(N, less, more):
	fromj = [1, 0]
	tillj = [0, 1]
	total = 1
	for i in range(1, N):
		if less[i] and more[i]:
			return 0
		if less[i]:
			dp = [tillj[j] % 1000000007 for j in range(i + 1)]
		elif more[i]:
			dp = [fromj[j] % 1000000007 for j in range(i + 1)]
		else:
			dp = [total % 1000000007 for j in range(i + 1)]
		total = sum(dp)
		f = total % 1000000007
		t = 0
		fromj = [total]
		tillj = [0]
		for j in range(i + 1):
			f -= dp[j]
			f = f % 1000000007
			fromj.append(f)
			t += dp[j]
			t = t % 1000000007
			tillj.append(t)
	return sum(dp) % 1000000007
