	def lenOfLongSubarr(self, arr, n, k) -> int:
		prefixMap = {0: -1}
		sumSoFar = 0
		maxWindowSize = 0
		for i in range(len(arr)):
			sumSoFar += arr[i]
			prefixSum = sumSoFar - k
			if prefixSum in prefixMap:
				left = prefixMap[prefixSum]
				right = i
				windowSize = right - left
				maxWindowSize = max(maxWindowSize, windowSize)
			if sumSoFar not in prefixMap:
				prefixMap[sumSoFar] = i
		return maxWindowSize
