", "class Solution:

	def lenOfLongSubarr(self, arr, n, k):
		max = 0
		sum_arr = [0] * n
		sum_arr[0] = arr[0]
		index_dict = {}
		index_dict[sum_arr[0]] = 0
		for i in range(1, n):
			sum_arr[i] = sum_arr[i - 1] + arr[i]
			if index_dict.get(sum_arr[i], True) == True:
				index_dict[sum_arr[i]] = i
		for i in range(n):
			diff = sum_arr[i] - k
			if diff == 0:
				result = i + 1
			else:
				j = index_dict.get(diff, -1)
				if j == -1 or j >= i:
					continue
				else:
					result = i - j
			if max < result:
				max = result
		return max
