def shift_left(n, ai, bi):
	if ai == bi:
		return n
	elif ai < bi:
		return bi - ai
	else:
		return n - (ai - bi)

def right_shift(n, ai, bi):
	if ai == bi:
		return n
	elif ai > bi:
		return ai - bi
	else:
		return n - (bi - ai)

def solve(n, a, b):
	num_idx = {ai: i for (i, ai) in enumerate(a)}
	zero_dist = 0
	dist1 = dict()
	dist2 = dict()
	for (i, bi) in enumerate(b):
		if bi in num_idx:
			if num_idx[bi] == i:
				zero_dist += 1
			d1 = shift_left(n, num_idx[bi], i)
			d2 = right_shift(n, num_idx[bi], i)
			if d1 in dist1:
				dist1[d1].append(bi)
			else:
				dist1[d1] = [bi]
			if d2 in dist2:
				dist2[d2].append(bi)
			else:
				dist2[d2] = [bi]
	mx = 0
	for (k, lst) in dist1.items():
		mx = max(mx, len(lst))
	for (k, lst) in dist2.items():
		mx = max(mx, len(lst))
	return max(mx, zero_dist)
