	f_l = []
	s_l = []
	for i in range(1, n + 1):
		if a[i] >= b[i]:
			f_l.append(a[i] - b[i])
			s_l.append(b[i] + n - a[i])
		else:
			f_l.append(a[i] + n - b[i])
