from itertools import combinations as combis
import sys
sys.setrecursionlimit(10000)

def cut_tree(n, k, G):
	ans = 1
	for nid in range(1, n + 1):
		if nid == 1:
			for ki in range(k + 1):
				ans += count_subtrees(G, 1, ki)
		else:
			for ki in range(k):
				ans += count_subtrees(G, nid, ki)
	return ans

def make_graph(n, G1):
	G2 = defaultdict(list)
	q = [1]
	visited = set()
	while q:
		nid = q.pop(0)
		visited.add(nid)
		for neigh_id in G1[nid]:
			if neigh_id in visited:
				continue
			G2[nid].append(neigh_id)
			q.append(neigh_id)
	return G2

def memoize(func):
	memo = {}

	def wrapper(G, nid, k):
		if (nid, k) not in memo:
			memo[nid, k] = func(G, nid, k)
		return memo[nid, k]
	return wrapper

@memoize
def count_subtrees(G, nid, k):
	if k < 0:
		return 0
	childs = G[nid]
	tot_childs = len(childs)
	ans = 1 if tot_childs == k else 0
	for cc in range(1, tot_childs + 1):
		unpicked = tot_childs - cc
		left_k = k - unpicked
		if left_k < 0:
			continue
		for picked in combis(childs, cc):
			for ks in dists(left_k, cc):
				sub_ans = 1
				for (child_id, child_k) in zip(picked, ks):
					sub_ans *= count_subtrees(G, child_id, child_k)
				ans += sub_ans
	return ans

def dists(k, cnt):
	stack = [([], k)]
	while stack:
		(ks, k_left) = stack.pop(-1)
		if len(ks) < cnt - 1:
			for k_part in range(k_left + 1):
				stack.append((ks + [k_part], k_left - k_part))
		elif len(ks) == cnt - 1:
			yield (ks + [k_left])

def height(n, G, n_id):
	h = 0
	for c_id in G[n_id]:
		h = max(h, height(n, G, c_id) + 1)
	return h

def cut_one_height_tree(n, k, G):
	ans = 2
	ans += n - 1
	for ki in range(1, k + 1):
		if ki > n - 1:
			break
		ans += combi_tot(n - 1, ki)
	return ans

def combi_tot(n, k):
	assert k >= 0 and n >= k
	if k > n - k:
		return combi_tot(n, n - k)
	ans = 1
	for i in range(k):
		ans = ans * (n - i) // (i + 1)
	return ans

