	def quicksort(self, array, low, high):
		if low < high:
			ind = self.partition(array, low, high)
			self.quicksort(array, low, ind - 1)
			self.quicksort(array, ind + 1, high)
		return array

	def partition(self, arr, lo, hi):
		piv = arr[hi]
		(i, j) = (lo, hi - 1)
		while i < j:
