				i += 1
			while arr[j] >= piv and j > lo:
				j -= 1
			if i < j:
				(arr[i], arr[j]) = (arr[j], arr[i])
		if arr[i] > piv:
			(arr[i], arr[hi]) = (arr[hi], arr[i])
		return i
