class Solution:

	def binarySearchable(self, Arr, n):
		max_to_left = [INT_MIN] * n
		min_to_right = [INT_MAX] * n
		for i in range(1, n):
			max_to_left[i] = max(max_to_left[i - 1], Arr[i - 1])
		for i in range(n - 2, -1, -1):
			min_to_right[i] = min(min_to_right[i + 1], Arr[i + 1])
		res = 0
		for i in range(n):
			if max_to_left[i] < Arr[i] and min_to_right[i] > Arr[i]:
				res += 1
		return res
