RANDOM = randint(1, 10 ** 9)

class hf(int):

	def __init__(self, x):
		int.__init__(x)

	def __hash__(self):
		return super(hf, self).__hash__() ^ RANDOM

def prune(A, B):
	n = len(A)
	bag = {}
	(nA, nB) = ([], [])
	for i in range(n):
		v = hf(A[i])
		if v not in bag:
			bag[v] = []
		bag[v].append(i)
	for i in range(n):
		v = hf(B[i])
		if v in bag and bag[v]:
			bag[v].pop()
			continue
		nB.append(B[i])
	for val in bag:
		for i in bag[val]:
			nA.append(A[i])
	return (nA, nB)

