MUST_BE_EMPTY = -1

def filling_the_grid(h: int, w: int, r: List[int], c: List[int]) -> int:
	cells = []
	for i in range(h):
		row = []
		for j in range(w):
			row.append(EMPTY)
		cells.append(row)
	num_of_undetermined_cells = w * h
	for i in range(h):
		num_of_full_cells = r[i]
		for j in range(num_of_full_cells):
			cells[i][j] = FULL
			num_of_undetermined_cells -= 1
		if num_of_full_cells < w:
			cells[i][num_of_full_cells] = MUST_BE_EMPTY
			num_of_undetermined_cells -= 1
	for j in range(w):
		num_of_full_cells = c[j]
		for i in range(num_of_full_cells):
			if cells[i][j] == MUST_BE_EMPTY:
				return 0
			if cells[i][j] != FULL:
				num_of_undetermined_cells -= 1
			cells[i][j] = FULL
		if num_of_full_cells < h:
			if cells[num_of_full_cells][j] == FULL:
				return 0
			if cells[num_of_full_cells][j] != MUST_BE_EMPTY:
				num_of_undetermined_cells -= 1
			cells[num_of_full_cells][j] = MUST_BE_EMPTY
