		if self.p[x] != x:
			self.p[x] = self.find(self.p[x])
		return self.p[x]

	def union(self, x, y):
		(xx, yy) = (self.find(x), self.find(y))
		if xx == yy:
			return True
		if self.r[xx] > self.r[yy]:
			self.p[yy] = xx
		elif self.r[yy] > self.r[xx]:
			self.p[xx] = yy
		else:
