def check_adjacent(vertex, g, rows, columns, colours):
	if vertex < rows * columns - columns:
		if colours[vertex] == colours[vertex + columns]:
			g.add_edge(vertex, vertex + columns)
	if vertex % columns != columns - 1:
		if colours[vertex] == colours[vertex + 1]:
			g.add_edge(vertex, vertex + 1)

def cycle_search(g, v, counter):
	reached = {}

	def do_dfs(curr, prev, init, count):
		if curr == init and count >= 4:
			return True
		if curr in reached:
			return False
		reached[curr] = prev
		for succ in g.neighbours(curr):
			if do_dfs(succ, curr, init, count + 1):
				return True
	return do_dfs(v, v, v, counter + 1)

