class Tile:

	def __init__(self, color: str, was_here: bool=False):
		self.color = color
		self.was_here = was_here

	def __str__(self) -> str:
		return f"|{(self.color if not self.was_here else '.')}|"

	def __repr__(self) -> str:
		return str(self)

def print_field(field: List[List[Tile]]):
	for row in field:
		for tile in row:
			print(tile, end='')
		print()

def get_neighbours(i: int, j: int, n: int, m: int):
	if j + 1 < m:
		yield (i, j + 1)
	if i + 1 < n:
		yield (i + 1, j)
	if j > 0:
		yield (i, j - 1)
	if i > 0:
		yield (i - 1, j)

def look_for_a_loop(field: List[List[Tile]], i: int, j: int, from_: Tuple[int, int]) -> bool:
	(n, m) = (len(field), len(field[0]))
	current = field[i][j]
	current.was_here = True
	from_tile = field[from_[0]][from_[1]]
	result = False
	for (ni, nj) in get_neighbours(i, j, n, m):
		neighbour = field[ni][nj]
		if neighbour == from_tile or neighbour.color != current.color:
			continue
		if neighbour.was_here:
			return True
		if look_for_a_loop(field, ni, nj, (i, j)):
			return True

