INF = 1234567890

def solve(io):
	N = io.readInt()
	B = io.readIntArray(N)
	if N == 1:
		io.println(0)
		return
	lo = (B[-1] - B[0] - 2) // (N - 1)
	hi = (B[-1] - B[0] + 2) // (N - 1)
	b0 = B[0]
	best = INF
	for s in range(b0 - 1, b0 + 2):
		B[0] = s
		for d in range(lo, hi + 1):
			best = min(best, abs(b0 - s) + req(B, d))
	if best == INF:
		io.println(-1)
	else:
		io.println(best)

def req(B, d):
	cnt = 0
	want = B[0]
	for i in range(1, len(B)):
		want += d
		if want != B[i]:
			if abs(want - B[i]) == 1:
				cnt += 1
			else:
				return INF
	return cnt

class IO:
	input = None
	output = None
	raw = ''
	buf = []
	pos = 0

	def __init__(self, inputStream, outputStream):
		self.input = inputStream
		self.output = outputStream

	def readToBuffer(self):
		self.raw = self.input.readline().rstrip('\n')
		self.buf = self.raw.split()
		self.pos = 0

	def readString(self):
		while self.pos == len(self.buf):
			self.readToBuffer()
		ans = self.buf[self.pos]
		self.pos += 1
		return ans

	def readInt(self):
		return int(self.readString())

	def readFloat(self):
		return float(self.readString())

	def readStringArray(self, N, offset=0):
		arr = [None] * offset
		for _ in range(0, N):
			arr.append(self.readString())
		return arr

	def readIntArray(self, N, offset=0):
		arr = [None] * offset
		for _ in range(0, N):
			arr.append(self.readInt())
		return arr

	def readFloatArray(self, N, offset=0):
		arr = [None] * offset
		for _ in range(0, N):
			arr.append(self.readFloat())
		return arr

	def readLine(self):
		while self.pos == len(self.buf):
			self.readToBuffer()
		if self.pos > 0:
			raise ValueError('Cannot call readline in the middle of a line.')
		return self.raw

	def print(self, s):
		self.output.write(str(s))

	def println(self, s):
		self.print(s)
		self.print('\n')

	def printlnArray(self, arr, sep=' '):
		self.println(sep.join((str(x) for x in arr)))

	def flushOutput(self):
		self.output.flush()
pythonIO = IO(sys.stdin, sys.stdout)
solve(pythonIO)
pythonIO.flushOutput()
