					visited.add(u)
		if len(visited) == len(G):
			return [G]
		else:
			unvisited = set(iter(G)) - visited
			component = subtract(G, unvisited)
			subgraph = subtract(G, visited)
			components = decompose(subgraph)
			components.append(component)
			return components

def subtract(G, vs):
	return dict(map(lambda x: (x[0], x[1] - vs), filter(lambda x: x[0] not in vs, G.items())))

def subgraph(G, vs):
	sg = {}
	for v in vs:
		sg[v] = G[v] & vs
	return sg

def compose(results):
	w = 0
	c = 1
	for (w1, c1) in results:
		w += w1
		c *= c1
	return (w, c)

def solve_small_0(G, ws):
	return (0, 1)

def solve_small_1(G, ws):
	if len(G) < 1:
		return solve_small_0(G, ws)
	(v,) = iter(G)
	if ws[v] == 0:
		return (0, 2)
	else:
		return (ws[v], 1)

def solve_small_2(G, ws):
	if len(G) < 2:
		return solve_small_1(G, ws)
	Gs = decompose(G)
	if len(Gs) > 1:
		res = [solve_small_2(g, ws) for g in Gs]
		return compose(res)
	(v, u) = G
	if ws[u] > ws[v]:
		return (ws[u], 1)
	elif ws[v] > ws[u]:
		return (ws[v], 1)
	elif ws[u] > 0:
		return (ws[u], 2)
	else:
		return (ws[u], 3)

def solve_small_3(G, ws):
	if len(G) < 3:
		return solve_small_2(G, ws)
	Gs = decompose(G)
	if len(Gs) > 1:
		res = [solve_small_3(g, ws) for g in Gs]
		return compose(res)
	(u, v, w) = iter(G)
	if v in G[u] and w in G[v] and (u in G[w]):
		if ws[u] == ws[v] and ws[v] == ws[w]:
			if ws[u] > 0:
				return (ws[u], 3)
			else:
				return (0, 4)
		else:
			x = min(u, v, w, key=lambda t: ws[t])
			return solve_small_2(subtract(G, {x}), ws)
	else:
		if G[w] == {u, v}:
			(u, w) = (w, u)
		elif G[v] == {u, w}:
			(u, v) = (v, u)
		if ws[u] == 0 and ws[v] == 0 and (ws[w] == 0):
			return (0, 5)
		elif ws[u] > ws[v] + ws[w]:
			return (ws[u], 1)
		elif ws[u] == ws[v] + ws[w]:
			return (ws[u], 1 + solve_small_2(subtract(G, {u}), ws)[1])
		else:
			return solve_small_2(subtract(G, {u}), ws)

def solve_choice(G, v, f, ws):
	(w1, c1) = f(subtract(G, {v}), ws)
	(w2, c2) = f(subtract(G, G[v] | {v}), ws)
	w2 += ws[v]
	if w1 > w2:
		return (w1, c1)
	elif w2 > w1:
		return (w2, c2)
	else:
		return (w1, c1 + c2)

def solve_degree_2(G, ws):
	if len(G) <= 3:
		return solve_small_3(G, ws)
	Gs = decompose(G)
	if len(Gs) > 1:
		res = [solve_degree_2(g, ws) for g in Gs]
		return compose(res)
	v = min(G.keys(), key=lambda x: len(G[x]))
	if len(G[v]) < 2:
		(last, v) = (v, next(iter(G[v])))
		for _ in range(len(G) // 2):
			(last, v) = (v, next(iter(G[v] - {last})))
	return solve_choice(G, v, solve_degree_2, ws)

def solve_degree_3(G, ws):
	if len(G) <= 3:
		return solve_small_3(G, ws)
	Gs = decompose(G)
	if len(Gs) > 1:
		res = [solve_degree_3(g, ws) for g in Gs]
		return compose(res)
	v = max(G.keys(), key=lambda x: len(G[x]))
	if len(G[v]) <= 2:
		return solve_degree_2(G, ws)
	hood = G[v] | {v}
	connectihood = {}
	for u in G[v]:
		for w in G[u]:
			if w not in hood:
				connectihood.add(u)
				break
	if len(connectihood) == 1:
		conn = connectihood.pop()
		(u, w) = G[v] - {conn}
		r1 = solve_degree_3(subtract(G, hood), ws)
		r2 = solve_small_3(subgraph(G, {v, u, w}), ws)
		(w1, c1) = combine([r1, r2])
		r1 = solve_degree_3(subtract(G, hood | G[conn]), ws)
		r2 = solve_small_2(subgraph(G, {u, w} - G[conn]), ws)
		(w2, c2) = combine([r1, r2])
		w2 += ws[conn]
		if w1 > w2:
			return (w1, c1)
		elif w1 < w2:
			return (w2, c2)
		else:
			return (w1, c1 + c2)
	else:
		return solve_choice(G, v, solve_degree_3, ws)

def solve(G, ws):
