		return solve_small_3(G, ws)
	Gs = decompose(G)
	if len(Gs) > 1:
		res = [solve(g, ws) for g in Gs]
		return compose(res)
	v = max(G.keys(), key=lambda x: len(G[x]))
	return solve_choice(G, v, solve, ws)

