from sys import stdin

def sp(neighbors, values):
	possible = []
	no_value_and_no_neighbor = 0
	min_max_val = 0
	for i in range(len(neighbors)):
		if neighbors[i]:
			possible.append(i)
			continue
		if values[i] > 0:
			min_max_val += values[i]
			continue
		no_value_and_no_neighbor += 1
	possible = tuple(possible)
	cache = {possible: 0}
	q = deque([(possible, 0)])
	max_val = 0
	max_val_covers = 0
	while q:
		(possible, value) = q.pop()
		if not possible:
			continue
		set_possible = set(possible[1:])
		set_possible.difference_update(neighbors[possible[0]])
		new_possible = tuple(sorted(list(set_possible)))
		new_value = value + values[possible[0]]
		if new_value > max_val:
			max_val = new_value
			max_val_covers = 1
		elif new_value == max_val:
			max_val_covers += 1
		other_new_possible = tuple(list(possible)[1:])
		if new_possible not in cache or cache[new_possible] <= new_value:
			cache[new_possible] = new_value
			q.append((new_possible, new_value))
		if other_new_possible not in cache or cache[other_new_possible] <= value:
			cache[other_new_possible] = value
			q.append((other_new_possible, value))
	if max_val == 0 and max_val_covers > 0:
		max_val_covers += 1
	if max_val_covers == 0:
		max_val_covers = 1
	max_val += min_max_val
	max_val_covers *= 2 ** no_value_and_no_neighbor
	print(max_val, max_val_covers)
