from collections import defaultdict

def _normalize_toll(value):
	if value >= 0:
		return value
	return 10 + value

class Graph:

	def __init__(self, vertices_d, edges_d):
		self.vertices_d = vertices_d
		self.edges_d = edges_d

	@property
	def root(self):
		return self.vertices_d.get(1)

	@property
	def vertices(self):
		return list(self.vertices_d.values())

	def edges(self, vertex):
		edges = self.edges_d.get(vertex, [])
		adjacent = []
		for edge in edges:
			if edge.v1 == vertex:
				adjacent.append(edge)
		return adjacent

	@classmethod
	def create(cls, road_from, road_to, road_weight):
		vertices_d = {}
		edges_d = defaultdict(list)
		for i in range(len(road_from)):
			(src, dst, w) = (road_from[i], road_to[i], road_weight[i])
			src = vertices_d.setdefault(src, Vertex(src))
			dst = vertices_d.setdefault(dst, Vertex(dst))
			edge1 = Edge(src, dst, w)
			edge2 = Edge(dst, src, (1000 - w) % 10, is_reversed=True)
			(edge1.reversed_edge, edge2.reversed_edge) = (edge2, edge1)
			edges_d[src].append(edge1)
			edges_d[dst].append(edge2)
		return Graph(vertices_d, edges_d)

